package com.example.myapplication;

import android.graphics.Bitmap;
import org.opencv.android.Utils;
import org.opencv.core.*;
import org.opencv.imgproc.Imgproc;
import java.util.*;

/** Conservative edge-skin mask and chroma-only moiré suppression. Both are optional and previewable. */
final class ScanCleanup {
    static Bitmap apply(Bitmap source,boolean fingers,boolean moire){if((fingers||moire)&&!com.paperflow.scanengine.ScanEngine.ready())throw new IllegalStateException(UiText.get(R.string.ui_image_processing_is_unavailable));Bitmap current=source;try{
        if(fingers){Bitmap mask=fingerMask(source);if(mask!=null)try{current=com.paperflow.scanengine.Inpainter.inpaint(current,mask);}finally{mask.recycle();}}
        if(moire){Bitmap next=chroma(current);if(current!=source)current.recycle();current=next;}return current;
    }catch(RuntimeException|OutOfMemoryError e){if(current!=source&&!current.isRecycled())current.recycle();throw e;}}
    private static Bitmap fingerMask(Bitmap source){float scale=Math.min(1,800f/Math.max(source.getWidth(),source.getHeight()));Bitmap small=Bitmap.createScaledBitmap(source,Math.max(1,Math.round(source.getWidth()*scale)),Math.max(1,Math.round(source.getHeight()*scale)),true);Mat rgba=new Mat(),rgb=new Mat(),ycc=new Mat(),skin=new Mat(),labels=new Mat(),stats=new Mat(),centroids=new Mat(),chosen=new Mat(),full=new Mat(),kernel=Imgproc.getStructuringElement(Imgproc.MORPH_ELLIPSE,new Size(5,5));try{
        Utils.bitmapToMat(small,rgba);Imgproc.cvtColor(rgba,rgb,Imgproc.COLOR_RGBA2RGB);Imgproc.cvtColor(rgb,ycc,Imgproc.COLOR_RGB2YCrCb);Core.inRange(ycc,new Scalar(45,135,75),new Scalar(255,182,135),skin);Imgproc.morphologyEx(skin,skin,Imgproc.MORPH_CLOSE,kernel);int count=Imgproc.connectedComponentsWithStats(skin,labels,stats,centroids);int w=small.getWidth(),h=small.getHeight();int[] pixels=new int[w*h];small.getPixels(pixels,0,w,0,0,w,h);boolean[] accepted=new boolean[count];int acceptedCount=0;
        for(int id=1;id<count;id++){int x=(int)stats.get(id,Imgproc.CC_STAT_LEFT)[0],y=(int)stats.get(id,Imgproc.CC_STAT_TOP)[0],cw=(int)stats.get(id,Imgproc.CC_STAT_WIDTH)[0],ch=(int)stats.get(id,Imgproc.CC_STAT_HEIGHT)[0],area=(int)stats.get(id,Imgproc.CC_STAT_AREA)[0];if(area<w*h*.0015||area>w*h*.08||cw<5||ch<5||!(x<3||y<3||x+cw>w-3||y+ch>h-3))continue;int whites=0,total=0;for(int yy=Math.max(0,y-8);yy<Math.min(h,y+ch+8);yy+=2)for(int xx=Math.max(0,x-8);xx<Math.min(w,x+cw+8);xx+=2){if(xx>=x&&xx<x+cw&&yy>=y&&yy<y+ch)continue;int p=pixels[yy*w+xx],r=(p>>16)&255,g=(p>>8)&255,b=p&255;total++;if(Math.min(r,Math.min(g,b))>165&&Math.max(r,Math.max(g,b))-Math.min(r,Math.min(g,b))<48)whites++;}if(total>0&&whites/(float)total>.6f){accepted[id]=true;acceptedCount++;}}
        if(acceptedCount==0)return null;int[] row=new int[w];byte[] maskRow=new byte[w];chosen.create(h,w,CvType.CV_8UC1);for(int y=0;y<h;y++){labels.get(y,0,row);for(int x=0;x<w;x++)maskRow[x]=(byte)(accepted[row[x]]?255:0);chosen.put(y,0,maskRow);}Imgproc.dilate(chosen,chosen,kernel);Imgproc.resize(chosen,full,new Size(source.getWidth(),source.getHeight()),0,0,Imgproc.INTER_NEAREST);Bitmap mask=Bitmap.createBitmap(source.getWidth(),source.getHeight(),Bitmap.Config.ARGB_8888);int[] output=new int[source.getWidth()];byte[] bytes=new byte[source.getWidth()];for(int y=0;y<source.getHeight();y++){full.get(y,0,bytes);for(int x=0;x<bytes.length;x++)output[x]=(bytes[x]&255)>0?0xffffffff:0;mask.setPixels(output,0,output.length,0,y,output.length,1);}return mask;
    }finally{if(small!=source)small.recycle();for(Mat m:new Mat[]{rgba,rgb,ycc,skin,labels,stats,centroids,chosen,full,kernel})m.release();}}
    private static Bitmap chroma(Bitmap source){Mat rgba=new Mat(),rgb=new Mat(),ycc=new Mat(),merged=new Mat(),out=new Mat();List<Mat> channels=new ArrayList<>();try{Utils.bitmapToMat(source,rgba);Imgproc.cvtColor(rgba,rgb,Imgproc.COLOR_RGBA2RGB);Imgproc.cvtColor(rgb,ycc,Imgproc.COLOR_RGB2YCrCb);Core.split(ycc,channels);for(int i=1;i<3;i++)Imgproc.GaussianBlur(channels.get(i),channels.get(i),new Size(7,7),1.6);Core.merge(channels,merged);Imgproc.cvtColor(merged,rgb,Imgproc.COLOR_YCrCb2RGB);Imgproc.cvtColor(rgb,out,Imgproc.COLOR_RGB2RGBA);Bitmap image=Bitmap.createBitmap(source.getWidth(),source.getHeight(),Bitmap.Config.ARGB_8888);Utils.matToBitmap(out,image);return image;}finally{for(Mat m:channels)m.release();for(Mat m:new Mat[]{rgba,rgb,ycc,merged,out})m.release();}}
}
